const {chromium}=require('playwright');const {expect}=require('playwright/test');const assert=require('node:assert/strict');const fs=require('node:fs');
const output=process.env.DEEP_CASH_OUTPUT||'.superpowers/deep-audit/cash-sessions';
const sizes=process.env.DEEP_CASH_SMOKE?[[390,844]]:[[320,700],[360,800],[390,844],[430,932],[768,1024],[1024,768],[1280,800],[1440,900]];
async function main(){const {createServer}=await import('vite');const server=await createServer({cacheDir:'.superpowers/vite-cash-cache',server:{host:'127.0.0.1',port:4456,strictPort:true}});await server.listen();const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});const results=[];fs.mkdirSync(output,{recursive:true});
try{for(const [width,height] of sizes)for(const theme of ['light','dark']){
 const context=await browser.newContext({viewport:{width,height},colorScheme:theme,hasTouch:width<=1024,reducedMotion:'reduce'});await context.route('https://fonts.googleapis.com/**',r=>r.abort());await context.addInitScript(t=>{if(location.protocol==='http:')localStorage.setItem('hisabiq-theme',t);},theme);await context.tracing.start({screenshots:true,snapshots:true,sources:true});const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));
 try{await page.goto('http://127.0.0.1:4456/#/app/finance',{waitUntil:'domcontentloaded'});const tab=page.getByRole('tab',{name:'Cash Sessions',exact:true});if(width<=1024)await tab.tap();else await tab.click();const table=page.getByRole('table');await expect(table.getByText('CS-000240',{exact:true})).toBeVisible();
 const geometry=await page.evaluate(()=>({viewport:innerWidth,width:document.documentElement.scrollWidth}));assert.ok(geometry.width<=width+2,'Cash Sessions must contain table scroll: '+JSON.stringify(geometry));
 const action=table.getByRole('button',{name:'Actions for CS-000240',exact:true});await action.focus();await action.press('Enter');const dialog=page.getByRole('dialog');await expect(dialog).toBeVisible();const r=await dialog.boundingBox();assert.ok(r.x>=0&&r.y>=0&&r.x+r.width<=width+1&&r.y+r.height<=height+1,'history dialog fits');await expect(dialog.getByText('CS-000240',{exact:false}).first()).toBeVisible();await expect(dialog.getByText('৳41,350',{exact:true})).toBeVisible();await expect(dialog.getByText('৳41,300',{exact:true})).toBeVisible();await page.keyboard.press('Escape');await expect(dialog).toHaveCount(0);await expect(action).toBeFocused();
 await page.getByRole('tab',{name:'Money Accounts',exact:true}).click();await tab.click();await expect(table.getByText('CS-000240',{exact:true})).toBeVisible();assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+2),true);assert.deepEqual(errors,[]);results.push({width,height,theme,status:'passed',geometry});
 }catch(e){console.error(width,theme,e.message);results.push({width,height,theme,status:'failed',error:e.message});await page.screenshot({path:output+'/'+width+'-'+theme+'.png',fullPage:true});}
 const failed=results.at(-1).status==='failed';await context.tracing.stop(failed?{path:output+'/'+width+'-'+theme+'-trace.zip'}:{});await context.close();console.log(width,theme,results.at(-1).status);
}}finally{fs.writeFileSync(output+'/results.json',JSON.stringify(results,null,2));await browser.close();await server.close();}assert.equal(results.filter(r=>r.status==='failed').length,0,'Cash session interaction failures');}
main().catch(e=>{console.error(e);process.exitCode=1;});
